import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = 0
    for a in op:
        if a == 'D':
            opp_d += 1
    my_d = 0
    for a in me:
        if a == 'D':
            my_d += 1

    if n == 1:
        return 'C'

    last_op = op[-1]
    last_me = me[-1]

    window = min(n, 12)
    recent = op[-window:]
    recent_c = 0
    for a in recent:
        if a == 'C':
            recent_c += 1
    recent_d = window - recent_c

    # Detect opponent cooperation profile over the whole match.
    opp_c = n - opp_d

    # Almost pure cooperator: build CC early, then exploit late.
    if opp_d == 0:
        if n < 88:
            return 'C'
        # Endgame grab: defect, but with a small chance to keep milking
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    if n >= 10 and opp_d * 10 <= n:
        # Opponent almost always cooperates. Maximize by alternating exploit
        # with cooperation to keep them cooperative.
        if n < 80:
            # Occasional exploitation while preserving cooperation.
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        if n < 95:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'D'

    # Almost pure defector: defect mostly, rare cooperative probes.
    if n >= 6 and opp_c * 10 <= n:
        if n < 92 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # Endgame: grab value, but respect a partner who is still cooperating.
    if n >= 96:
        if opp_c * 4 >= n * 3 and last_op == 'C':
            return 'C'
        return 'D'

    if n >= 90:
        if last_op == 'C' and recent_c >= window - 1:
            return 'C'
        return 'D'

    # Detect a defection streak and respond firmly but briefly.
    run_d = 0
    for a in reversed(op):
        if a == 'D':
            run_d += 1
        else:
            break

    run_c = 0
    for a in reversed(op):
        if a == 'C':
            run_c += 1
        else:
            break

    # Opponent defected last round.
    if last_op == 'D':
        if run_d >= 3:
            # Long punishment phase, but probe to try restoring cooperation
            # if we ourselves have been defecting for a while.
            my_run_d = 0
            for a in reversed(me):
                if a == 'D':
                    my_run_d += 1
                else:
                    break
            if my_run_d >= 3:
                return 'C'
            return 'D'
        if run_d == 2:
            return 'D'
        # Single defection: forgive sometimes to avoid mutual retaliation,
        # otherwise give a short one-round punishment.
        if run_c >= 5 and rng.random() < 0.6:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if recent_d * 4 >= window:
        # Opponent still fairly defective recently; be cautious but conciliatory.
        if my_d >= 3 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent is cooperating: mostly cooperate, with light probing.
    if opp_c * 5 >= n * 4:
        # Mostly cooperative partner; probe rarely to detect exploiters
        # but keep CC streak alive.
        if n >= 20 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Mixed partner: cooperate if they recently cooperated, defect if mixed.
    if recent_c * 2 >= window:
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    if rng.random() < 0.6:
        return 'C'
    return 'D'
